module.exports = function(data) {
    const stock = data["stock.json"];
    const prices = data["prices.json"];

    if (!stock || typeof stock !== 'object' || !prices || typeof prices !== 'object') {
        return [];
    }

    // 1. Filter for positive quantity items and maintain stock order
    const positiveStock = stock.filter(item => item.qty > 0);

    // 2. Map to the required structure: { sku: string, valueCents: number }
    const result = positiveStock.map(item => {
        const sku = item.sku;
        const qty = item.qty;
        const price = prices[sku];

        // Ensure price exists before calculation, although based on input structure, it should.
        if (typeof price === 'number') {
            // valueCents = qty * price (assuming price is already in cents or the unit matches qty)
            // Given the example (qty=3, price=120), the result should be 360.
            const valueCents = qty * price;
            return {
                sku: sku,
                valueCents: valueCents
            };
        }
        // Handle case where price might be missing or invalid for robustness
        return null;
    }).filter(item => item !== null); // Remove any null entries if price was missing

    return result;
};

